DECLARE v_api_url text; v_api_key text; v_row record; v_conn record; v_endpoint text; v_body jsonb; v_req_id bigint; v_sent int := 0; v_skipped int := 0; v_failed int := 0; v_number text; v_local text;
BEGIN
  v_api_url := ops.fn_evo_url();
  v_api_key := ops.fn_evo_key();
  IF v_api_url IS NULL OR v_api_key IS NULL THEN RAISE EXCEPTION '[fn_outbound_dispatch] vault secrets faltando'; END IF;
  FOR v_row IN SELECT q.* FROM zapp.outbound_message_queue q WHERE q.status='pending' AND coalesce(q.retry_count,0) < coalesce(q.max_retries,3) ORDER BY q.created_at ASC LIMIT p_batch_size FOR UPDATE SKIP LOCKED LOOP
    SELECT status INTO v_conn FROM zapp.whatsapp_connections WHERE instance_name=v_row.instance_name LIMIT 1;
    IF v_conn IS NULL OR v_conn.status <> 'connected' THEN v_skipped := v_skipped + 1; CONTINUE; END IF;
    -- normaliza JID (LID-fix via zapp.fn_normalize_send_jid) e valida content/media_url
    IF v_row.message_type='text' OR v_row.message_type IS NULL THEN v_endpoint := v_api_url||'/message/sendText/'||v_row.instance_name; v_body := jsonb_build_object('number',v_number,'text',v_row.content);
    ELSIF v_row.message_type='audio' THEN v_endpoint := v_api_url||'/message/sendMedia/'||v_row.instance_name; v_body := jsonb_build_object('number',v_number,'mediatype','audio','mimetype',coalesce(v_row.media_mime_type,'audio/ogg; codecs=opus'),'media',v_row.media_url,'ptt',coalesce(v_row.ptt,true));
    ELSE v_endpoint := v_api_url||'/message/sendMedia/'||v_row.instance_name; v_body := jsonb_build_object('number',v_number,'mediatype',v_row.message_type,'mimetype',coalesce(v_row.media_mime_type,'application/octet-stream'),'media',v_row.media_url,'caption',v_row.caption,'fileName',coalesce((v_row.metadata->>'fileName')::text,'file')); END IF;
    v_req_id := net.http_post(url:=v_endpoint, body:=v_body, headers:=jsonb_build_object('apikey',v_api_key,'Content-Type','application/json'), params:='{}', timeout_milliseconds:=10000);
    UPDATE zapp.outbound_message_queue SET status='sending', external_id=v_req_id::text, sent_at=now(), updated_at=now() WHERE id=v_row.id;
    v_sent := v_sent + 1;
    -- EXCEPTION WHEN OTHERS: retry_count+1, status failed (>=max_retries) ou pending
  END LOOP;
  RETURN jsonb_build_object('dispatched_at',now(),'sent',v_sent,'skipped',v_skipped,'failed',v_failed,'provider','evolution');
END;

DECLARE
  v_cfg record; v_alert record; v_url text; v_key text; v_resend_key text; v_ext_url text; v_payload jsonb; v_sent int := 0; v_conn_ok boolean := false;
BEGIN
  SELECT * INTO v_cfg FROM ops.notification_config WHERE id=1 AND enabled;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'reason','config_ausente_ou_desabilitada'); END IF;
  v_url := ops.fn_evo_url();
  v_key := ops.fn_evo_key();
  SELECT decrypted_secret INTO v_resend_key FROM vault.decrypted_secrets WHERE name='resend_api_key';
  SELECT decrypted_secret INTO v_ext_url FROM vault.decrypted_secrets WHERE name='external_notification_url';
  -- guard de sessao: wpp2 connected < 10min (zapp.whatsapp_connections)
  FOR v_alert IN SELECT * FROM ops.pending_critical_alerts WHERE notified_at IS NULL ORDER BY created_at LIMIT 5 LOOP
    -- Canal WhatsApp (somente se wpp conectado e resolvers ok)
    PERFORM net.http_post(url:=rtrim(v_url,'/')||'/message/sendText/'||v_cfg.instance, headers:=jsonb_build_object('Content-Type','application/json','apikey',v_key), body:=jsonb_build_object('number',v_cfg.target_jid,'text',chr(128680)||' *ALERTA CRITICO ZAPP WEBB*'||chr(10)||coalesce(v_alert.message,'')||' #'||v_alert.alert_type), params:='{}', timeout_milliseconds:=5000);
    -- Canal webhook externo
    PERFORM net.http_post(url:=v_ext_url, headers:=jsonb_build_object('Content-Type','application/json'), body:=jsonb_build_object('severity','critical','alert_type',v_alert.alert_type,'message',coalesce(v_alert.message,''),'title',coalesce(v_alert.title,v_alert.alert_type),'created_at',v_alert.created_at::text,'source','fn_notify_critical_alerts_v6'), params:='{}', timeout_milliseconds:=5000);
    -- Canal email Resend
    PERFORM net.http_post(url:='https://api.resend.com/emails', headers:=jsonb_build_object('Authorization','Bearer '||v_resend_key,'Content-Type','application/json'), body:=jsonb_build_object('from','AtomicaBR Alertas <alertas@promobrindes.com.br>','to',ARRAY['ti@promobrindes.com.br'],'subject',chr(128680)||' [CRITICO] '||coalesce(v_alert.title,v_alert.alert_type),'html','<div style="font-family:Arial">Alerta Critico ZAP WEBB</div>'), params:='{}', timeout_milliseconds:=10000);
    UPDATE ops.pending_critical_alerts SET notified_at = now() WHERE id = v_alert.id;
    v_sent := v_sent + 1;
  END LOOP;
  RETURN jsonb_build_object('ok',true,'sent',v_sent,'wpp_session',v_conn_ok,'triple_channel',true,'version','v6-fix-pending-view-20260814');
EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('ok',false,'error',SQLERRM,'version','v6');
END;

DECLARE v_http_code int; v_body text; v_status text; v_falhas int;
BEGIN
  PERFORM net.http_get('https://evolution.atomicabr.com.br/license/status');
  PERFORM pg_sleep(7);
  SELECT status_code, content::text INTO v_http_code, v_body FROM net._http_response WHERE created > now() - interval '30 seconds' ORDER BY id DESC LIMIT 1;
  v_status := CASE WHEN v_http_code = 200 AND (v_body ~ '"ok"\s*:\s*true' OR v_body ~ '"status"\s*:\s*"active"') THEN 'active' ELSE COALESCE(v_body, 'sem_resposta') END;
  INSERT INTO zapp.license_heartbeat_log (checked_at, status, http_code, raw) VALUES (now(), v_status, COALESCE(v_http_code,0), left(COALESCE(v_body,''),500));
  -- se >=3 falhas na ultima hora: insere alerta critical em zapp.evolution_alerts (dedup 2h)
  RETURN v_status;
END;

DECLARE v_instance_id text; v_cooldown_ok boolean; v_webhook_payload jsonb;
BEGIN
  IF NEW.instance_name != 'wpp2' THEN RETURN NEW; END IF;
  IF NEW.state NOT IN ('closed','disconnected','logout') THEN RETURN NEW; END IF;
  -- cooldown 5min via evo.evolution_bootstrap_log (triggered_by='auto-connection-trigger')
  -- registra no bootstrap_log (acao critica) e monta payload LOGOUT_INSTANCE
  PERFORM net.http_post(url := 'https://webhook.atomicabr.com.br/webhook/evolution-bootstrap-alert', body := v_webhook_payload, headers := '{"Content-Type":"application/json"}'::jsonb);
  RAISE WARNING 'Bootstrap Alert: wpp2 state->%. Bootstrap registered + n8n notified.', NEW.state;
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN RAISE WARNING 'Bootstrap trigger error (non-fatal): %', SQLERRM; RETURN NEW;
END;

DECLARE v_lusha_cookie TEXT; v_lc_cookie TEXT; v_li_cookie TEXT; v_li_csrf TEXT; v_req_lusha BIGINT; v_req_lc BIGINT; v_req_li BIGINT; v_total_reqs INT := 0;
BEGIN
  -- le cookies de zapp.cookies_config (servicos lusha/leadcontact/linkedin)
  -- dispara 3 requests pg_net em PARALELO:
  IF length(coalesce(v_lusha_cookie,'')) > 20 THEN
    SELECT net.http_get(url := 'https://dashboard-services.lusha.com/v2/filters/companyName?text=PROBE', headers := jsonb_build_object('Cookie',v_lusha_cookie,'Origin','https://dashboard.lusha.com','Referer','https://dashboard.lusha.com/','User-Agent','Mozilla/5.0'), timeout_milliseconds := 6000) INTO v_req_lusha;
    v_total_reqs := v_total_reqs + 1; END IF;
  IF length(coalesce(v_lc_cookie,'')) > 10 THEN
    SELECT net.http_post(url := 'https://api.leadcontact.ai/api/auth/check_login', body := '{}'::jsonb, headers := jsonb_build_object('Cookie',v_lc_cookie,'Content-Type','application/json','Origin','chrome-extension://imhlnhlbiencamnbpigopiibddajimep','User-Agent','Mozilla/5.0'), timeout_milliseconds := 6000) INTO v_req_lc;
    v_total_reqs := v_total_reqs + 1; END IF;
  IF length(coalesce(v_li_cookie,'')) > 20 THEN
    SELECT net.http_get(url := 'https://www.linkedin.com/voyager/api/me', headers := jsonb_build_object('Cookie',v_li_cookie,'csrf-token',coalesce(v_li_csrf,''),'Accept','application/vnd.linkedin.normalized+json+2.1','x-restli-protocol-version','2.0.0','User-Agent','Mozilla/5.0'), timeout_milliseconds := 6000) INTO v_req_li;
    v_total_reqs := v_total_reqs + 1; END IF;
  -- loop unificado aguardando respostas (18x pg_sleep(0.5) max) via net._http_response
  -- atualiza zapp.cookies_config (is_healthy/health_status 200/401/403/429) e grava cookie_probe_log
  -- PERFORM zapp.fn_circuit_record(servico, healthy) para o circuit breaker
  RETURN jsonb_build_object('probed_at',now(),'requests_fired',v_total_reqs,'req_ids',jsonb_build_object('lusha',v_req_lusha,'leadcontact',v_req_lc,'linkedin',v_req_li));
END;

DECLARE v_supabase_url text := 'https://supabase.atomicabr.com.br'; v_service_key text; v_health_secret text; v_row RECORD; v_request_id bigint; v_queued int := 0; MAX_CONCURRENT CONSTANT int := 15;
BEGIN
  SELECT decrypted_secret INTO v_service_key FROM vault.decrypted_secrets WHERE name='supabase_service_role_key' LIMIT 1;
  SELECT decrypted_secret INTO v_health_secret FROM vault.decrypted_secrets WHERE name='health_secret' LIMIT 1;
  -- recupera audios travados (processing>15min / expired / failed concurrent_limit)
  -- guard de concorrencia: MAX_CONCURRENT=15; seleciona batch de mensagens de audio wpp2 (media_status='ready')
  SELECT net.http_post(url := v_supabase_url || '/functions/v1/transcribe-audio-internal', body := jsonb_build_object('messageId', v_row.message_id, 'audioUrl', v_row.media_url), headers := jsonb_build_object('Content-Type','application/json','Authorization','Bearer ' || v_service_key,'x-internal-secret', v_health_secret), timeout_milliseconds := 120000) INTO v_request_id;
  v_queued := v_queued + 1;
  RETURN jsonb_build_object('ok', true, 'queued', v_queued, 'first_request_id', v_request_id, 'timeout_ms', 120000, 'executed_at', now());
EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('ok', false, 'error', SQLERRM);
END;
